import { Form, Modal, Select } from 'antd'
import { CopyPresetStyle } from './index.style'
import PropTypes from 'prop-types'
const CopyPreset = (props) => {
  const { visible, onCancel, form, onSubmit, presetList = [] } = props
  const { getFieldDecorator } = form
  const handleSubmit = () => {
    form.validateFields((errors, values) => {
      if (!errors) {
        onSubmit(values)
      }
    })
  }
  const fieldElement = (
    <Select
      placeholder='Select Preset to copy'
      showSearch
      filterOption={(input, option) =>
        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0 ||
        option.props.value.toLowerCase().indexOf(input.toLowerCase()) >= 0}
    >
      {
        presetList && presetList.map(value => (
          <Select.Option
            value={value?.preset_uuid}
            key={value?.preset_uuid}
          >
            {value?.name}
          </Select.Option>
        ))
      }
    </Select>
  )
  return (
    <Modal visible={visible} onCancel={onCancel} onOk={handleSubmit} title='Copy Preset Data'>
      <CopyPresetStyle>
        <Form>
          <Form.Item>
            {getFieldDecorator('preset', {
              rules: [
                {
                  required: true,
                  message: 'Please Select a Preset!'
                }
              ]
            })(fieldElement)}
          </Form.Item>
        </Form>
      </CopyPresetStyle>
    </Modal>
  )
}

CopyPreset.propTypes = {
  visible: PropTypes.bool.isRequired,
  onCancel: PropTypes.func.isRequired,
  onSubmit: PropTypes.func.isRequired
}

const withFormCopyPreset = Form.create()(CopyPreset)

export default withFormCopyPreset
