import { Button, Col, Form, Icon, InputNumber, Radio, Row, Select } from 'antd'
import { TieringStyle } from './index.style'
import RadioGroup from 'antd/lib/radio/group'
import get from 'lodash/get'
import { useEffect, useRef, useState } from 'react'
import PropTypes from 'prop-types'

let whcId = 1001
let wohcId = 1001

const PREMIUM_TYPE_OPTIONS = [
  { label: 'Gross Premium', value: 'gross_premium' },
  { label: 'Net Premium', value: 'net_premium' },
  { label: 'Basic Premium', value: 'basic_premium' }
]

const Tiering = (props) => {
  const { form, type = 'stamp_duty', tieringData = {} } = props
  const { getFieldDecorator, getFieldValue, setFieldsValue } = form
  const prevTieringData = useRef(tieringData)
  const [isNewTiering, setIsNewTiering] = useState(false)
  useEffect(() => {
    if (prevTieringData.current !== tieringData) {
      setIsNewTiering(true)
    } else {
      setIsNewTiering(false)
    }
  }, [tieringData])
  const remove = (k, hardcopy = 'with_hard_copy') => {
    const keys = getFieldValue(`${type}.${hardcopy}_keys`)
    if (keys.length === 1) {
      return
    }
    setFieldsValue({
      [`${type}.${hardcopy}_keys`]: keys.filter(key => key !== k)
    })
  }

  const add = (hardcopy = 'with_hard_copy') => {
    const keys = getFieldValue(`${type}.${hardcopy}_keys`)
    const nextKeys = keys.concat(`${type}_${hardcopy}_${hardcopy === 'with_hard_copy' ? whcId++ : wohcId++}`)
    setFieldsValue({
      [`${type}.${hardcopy}_keys`]: nextKeys
    })
  }

  const onMaxChange = (value, nextKey, hardcopy) => {
    if (value >= 0) {
      setFieldsValue({
        [`${type}.${hardcopy}.tiering.${nextKey}.min`]: value + 1
      })
    }
  }

  const renderFormItem = (
    {
      type,
      placeholder = '',
      data = [],
      name,
      step = 1,
      disabled = false,
      min,
      max,
      required,
      error = '',
      title = '',
      pattern,
      hidden = false,
      dropdownKey = 'value',
      dropdownValue = 'label',
      radioKey = 'value',
      radioValue = 'label',
      onChange = () => {},
      initialValue = ''
    }) => {
    let fieldElement = ''

    switch (type) {
      case 'select':
        fieldElement = (
          <Select
            placeholder={placeholder}
            disabled={disabled}
            size='small'
          >
            {
              data.map(value => (
                <Select.Option
                  value={value[dropdownKey]}
                  key={value[dropdownKey]}
                >
                  {value[dropdownValue]}
                </Select.Option>
              ))
            }
          </Select>
        )
        break
      case 'radio-group':
        fieldElement = (
          <RadioGroup disabled={disabled}>
            {
              data.map(value => (
                <Radio
                  value={value[radioKey]}
                  key={value[radioKey]}
                >
                  {value[radioValue]}
                </Radio>
              ))
            }
          </RadioGroup>
        )
        break
      case 'number':
        fieldElement = (
          <InputNumber
            placeholder={placeholder}
            type='number'
            className='number-format'
            decimalSeparator='.'
            min={min}
            max={max}
            step={step}
            disabled={disabled}
            size='small'
            onChange={onChange}
          />
        )
        break
      default:
        return null
    }
    return (
      <Form.Item className={`new-margin${hidden ? ' field-hidden' : ''}`}>
        {getFieldDecorator(name, {
          rules: [
            {
              required,
              message: error || `Please Enter ${title}!`,
              ...(pattern ? { pattern } : {})
            }
          ],
          ...(initialValue !== '' ? { initialValue } : {})
        })(fieldElement)}
      </Form.Item>
    )
  }

  getFieldDecorator(`${type}.with_hard_copy_keys`, { initialValue: [`${type}_with_hard_copy_1000`] })
  getFieldDecorator(`${type}.without_hard_copy_keys`, { initialValue: [`${type}_without_hard_copy_1000`] })
  const keys = (hardcopy = 'with_hard_copy') => getFieldValue(`${type}.${hardcopy}_keys`)
  const Items = (hardcopy = 'with_hard_copy', hidden = false) => {
    const keyList = keys(hardcopy)
    const values = keyList.map((k, index) => {
      const prevKey = keyList[index - 1]
      const nextKey = keyList[index + 1]
      const min = get(tieringData, `${type}.${hardcopy}[${k}].min`)
      const max = get(tieringData, `${type}.${hardcopy}[${k}].max`)
      const fee = get(tieringData, `${type}.${hardcopy}[${k}].fee`)
      const rendered = (
        <Row className={hidden ? 'field-hidden' : ''} key={k} type='flex' justify='end' align='top'>
          <Col className='form-col-width number'>
            {
              keys(hardcopy).length !== 1 && keys(hardcopy).length === index + 1 &&
                <Icon
                  size='small'
                  type='close'
                  className='remove-btn'
                  onClick={() => remove(k, hardcopy)}
                />
            }
            {
              renderFormItem({
                placeholder: 'Minimum Amount',
                name: `${type}.${hardcopy}.tiering.${k}.min`,
                type: 'number',
                required: true,
                title: 'Min Amt',
                disabled: index !== 0,
                initialValue: isNewTiering && min >= 0 ? min : (index !== 0 ? getFieldValue(`${type}.${hardcopy}.tiering.${prevKey}.max`) + 1 : '')
              })
            }
          </Col>
          <Col className='form-col-width number margin'>
            {
              renderFormItem({
                placeholder: 'Maximum Amount',
                name: `${type}.${hardcopy}.tiering.${k}.max`,
                type: 'number',
                required: true,
                title: 'Max Amt',
                initialValue: isNewTiering && max >= 0 ? max : '',
                min: getFieldValue(`${type}.${hardcopy}.tiering.${k}.min`) + 1 || 1,
                onChange: (value) => onMaxChange(value, nextKey, hardcopy)
              })
            }
          </Col>
          <Col className='form-col-width plaintext'>=</Col>
          <Col className='form-col-width number'>
            {
              renderFormItem({
                placeholder: 'Amount',
                name: `${type}.${hardcopy}.tiering.${k}.fee`,
                type: 'number',
                required: true,
                title: 'Amount',
                min: 0,
                initialValue: isNewTiering ? fee : ''
              })
            }
          </Col>
          <Col className='form-col-width plaintext'>
            <div className='add-more-button'>
              {
                index === keys(hardcopy).length - 1 && (
                  <Button type='link' size='small' onClick={() => add(hardcopy)}>
                    <Icon type='plus' size='small' className='plus-icon' />
                    Add More
                  </Button>
                )
              }
            </div>
          </Col>
        </Row>
      )
      return rendered
    })
    return (
      <>
        <Row className={hidden ? 'field-hidden' : ''} type='flex' justify='start'>
          <Col className='form-col-width select'>
            {
              renderFormItem({
                placeholder: 'Select premium type',
                name: `${type}.${hardcopy}.premium_type`,
                data: PREMIUM_TYPE_OPTIONS,
                dropdownKey: 'value',
                dropdownValue: 'label',
                required: true,
                type: 'select',
                title: 'Premium Type'
              })
            }
          </Col>
        </Row>
        {values}
      </>
    )
  }
  return (
    <TieringStyle>
      <Row type='flex' justify='start'>
        <Col>
          <div className='hc-title whc'>with hardcopy</div>
        </Col>
        <Col>
          {
            renderFormItem(
              {
                type: 'radio-group',
                name: `${type}.with_hard_copy_type`,
                required: true,
                data: [
                  {
                    value: 'flat',
                    label: 'Flat'
                  },
                  {
                    value: 'tiering',
                    label: 'Tiering'
                  }
                ]
              }
            )
          }
        </Col>
      </Row>
      {
        Items('with_hard_copy', form.getFieldValue(`${type}.with_hard_copy_type`) !== 'tiering')
      }
      {
        renderFormItem({
          placeholder: '',
          name: `${type}.with_hard_copy.flat`,
          type: 'number',
          required: true,
          title: 'Amount',
          min: 0,
          hidden: form.getFieldValue(`${type}.with_hard_copy_type`) === 'tiering'
        })
      }
      <Row type='flex' justify='start'>
        <Col>
          <div className='hc-title'>without hardcopy</div>
        </Col>
        <Col>
          {
            renderFormItem(
              {
                type: 'radio-group',
                name: `${type}.without_hard_copy_type`,
                required: true,
                data: [
                  {
                    value: 'flat',
                    label: 'Flat'
                  },
                  {
                    value: 'tiering',
                    label: 'Tiering'
                  }
                ]
              }
            )
          }
        </Col>
      </Row>
      {
        Items('without_hard_copy', form.getFieldValue(`${type}.without_hard_copy_type`) !== 'tiering')
      }
      {
        renderFormItem({
          placeholder: '',
          name: `${type}.without_hard_copy.flat`,
          type: 'number',
          required: true,
          title: 'Amount',
          min: 0,
          hidden: form.getFieldValue(`${type}.without_hard_copy_type`) === 'tiering'
        })
      }
    </TieringStyle>
  )
}

Tiering.propTypes = {
  type: PropTypes.string,
  tieringData: PropTypes.object,
  form: PropTypes.object
}

export default Tiering
