import { Col, Row } from 'antd'
import moment from 'moment-timezone'

const formDateElements = (renderFormItemWithLabel, renderFormItem, disabledDate) => {
  return (
    renderFormItemWithLabel(
      (
        <Row type='flex'>
          <Col>
            {
              renderFormItem({
                name: 'preset_start_date',
                title: 'Start Date',
                placeholder: 'Start Date',
                type: 'datepicker',
                required: true,
                disabledDate: moment(),
                disabledDateScenario: 'minimum'
              })
            }
          </Col>
          <Col className='start-date-to'>To</Col>
          <Col>
            {
              renderFormItem({
                name: 'preset_end_date',
                title: 'End Date',
                placeholder: 'End Date',
                type: 'datepicker',
                required: true,
                defaultDatePicker: moment(disabledDate).add(1, 'days'),
                disabledDate: disabledDate,
                disabled: !disabledDate // means if start date is not select then disabled end date
              })
            }
          </Col>
        </Row>
      ),
      'Effective Date'
    )
  )
}

export default formDateElements
