import { Button, DatePicker, Form, Input, InputNumber, Radio, Row, Select } from 'antd'
import RadioGroup from 'antd/lib/radio/group'
import get from 'lodash/get'
import moment from 'moment-timezone'
import { useEffect, useRef, useState } from 'react'
import { decimalTwoDigit } from '../../../../../helpers/utility'
import { getTieringError } from '../../helpers/constants'
import { formDataToEdit, formDataToCopy, formToFormData } from '../../helpers/converters'
import Tiering from '../Tiering'
import ViewPreset from '../ViewPreset'
import formDateElements from './renderFunctions/formDateElements'
import { BF_FIELDS, DiscountFields, EF_FIELDS, HARD_COPY_STATUS } from './constants'
import { PresetFormStyle } from './index.style'
import slaElements from './renderFunctions/slaElements'

const PresetForm = (props) => {
  const {
    form,
    isEdit,
    presetData,
    editPresetData,
    fixedProvider,
    packageList = [],
    providerList = [],
    productList = [],
    setShowCopyButton = () => {},
    onSubmit = () => {},
    previewRef
  } = props
  const [editPreset, setEditPreset] = useState({})
  const { getFieldValue, getFieldDecorator, resetFields } = form
  const [isReview, setIsReview] = useState(false)
  previewRef.current = () => setIsReview(false)
  const [formVals, setFormVals] = useState({})
  const [tieringData, setTieringData] = useState({})
  const [selectData, setSelectData] = useState({
    provider: '',
    product: '',
    package: ''
  })
  const formRef = useRef(form)

  useEffect(() => {
    formRef.current = form
  }, [form])

  useEffect(() => {
    if (presetData) {
      const [formVals, tierings] = formDataToCopy(presetData)
      setTieringData(tierings)
      formRef.current.setFieldsValue(formVals)
    }
  }, [presetData])

  useEffect(() => {
    if (editPresetData) {
      const [formVals, tierings] = formDataToEdit(editPresetData)
      const {
        provider,
        package: pkg,
        product,
        preset_type: presetType,
        code,
        is_active: isActive,
        ...newFormVals
      } = formVals
      setTieringData(tierings)
      formRef.current.setFieldsValue(newFormVals)
      setEditPreset({
        provider,
        package: pkg,
        product,
        preset_type: presetType,
        code,
        is_active: isActive
      })
    }
  }, [editPresetData])

  const disabledDate = getFieldValue('preset_start_date')

  const handleNumberChange = (name, value) => {
    if ([
      'agent_bf_commission_percent',
      'pasarpolis_bf_commission_percent',
      'discount_percent',
      'agent_ef_commission_percent',
      'pasarpolis_ef_commission_percent'
    ].includes(name)) {
      if ((value > 100) && value.length > 3) {
        value = value.substr(0, 3) === '100' ? '100' : value
      }
      if (value <= 100) {
        if (value.includes('.')) {
          return parseFloat(decimalTwoDigit(value))
        }
        return value
      }
      return value.substr(0, 2)
    }
    return value
  }
  const handleDisabledDate = (current, disabledDate, disabledDateScenario = 'default', disabledNextDate) => {
    if (disabledDate) {
      switch (disabledDateScenario) {
        case 'minimum':
          return current && (current < moment(disabledDate).startOf('day'))
        default:
          return current && (current < moment(disabledDate).endOf('day'))
      }
    }
    return false
  }
  const handleDatePickerChange = (name) => {
    if (name === 'preset_start_date') {
      resetFields(['preset_end_date'])
    }
  }
  const renderFormItem = (
    {
      type, placeholder, maxLength = false, data = [],
      name, step = 1, disabled, min,
      max, required, error = '',
      title = '', pattern, hidden = false,
      dropdownKey = 'value', dropdownValue = 'label',
      radioKey = 'value', radioValue = 'label',
      disabledDate, disabledDateScenario = 'default',
      defaultDatePicker, disabledNextDate, isDay,
      showSearch = false
    }) => {
    let fieldElement = ''

    switch (type) {
      case 'text':
        fieldElement = (
          <Input
            type={type}
            placeholder={placeholder}
            maxLength={maxLength}
            disabled={disabled}
          />
        )
        break
      case 'select':
        fieldElement = (
          <Select
            placeholder={placeholder}
            showSearch={showSearch}
            disabled={disabled}
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0 ||
              option.props.value.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          >
            {
              data?.map(value => (
                <Select.Option
                  value={value[dropdownKey]}
                  key={value[dropdownKey]}
                >
                  {value[dropdownValue]}
                </Select.Option>
              ))
            }
          </Select>
        )
        break
      case 'radio-group':
        fieldElement = (
          <RadioGroup disabled={disabled}>
            {
              data?.map(value => (
                <Radio
                  value={value[radioKey]}
                  key={value[radioKey]}
                >
                  {value[radioValue]}
                </Radio>
              ))
            }
          </RadioGroup>
        )
        break
      case 'percentage':
      case 'number':
        fieldElement = (
          <InputNumber
            type='number'
            className={`number-format${type === 'percentage' ? ' percentage-input' : ''}${isDay ? ' is-day' : ''}`}
            decimalSeparator='.'
            min={min}
            max={max}
            step={step}
            parser={(value) => handleNumberChange(name, value)}
            placeholder={placeholder}
            disabled={disabled}
          />
        )
        break
      case 'datepicker':
        fieldElement = (
          <DatePicker
            disabledDate={
              (current) => handleDisabledDate(
                current, disabledDate, disabledDateScenario, disabledNextDate
              )
            }
            disabled={disabled}
            placeholder={placeholder}
            defaultPickerValue={defaultDatePicker}
            onChange={() => handleDatePickerChange(name)}
            format='DD-MM-YYYY'
          />
        )
        break
      default:
        return null
    }

    return (
      <Form.Item>
        {getFieldDecorator(name, {
          rules: [
            {
              required,
              message: error || `Please Enter ${title}!`,
              ...(pattern ? { pattern } : {})
            }
          ]
        })(fieldElement)}
      </Form.Item>
    )
  }

  const renderFormItemWithLabel = (component, label, className, hidden = false) => {
    return (
      <div className={`preset-field ${hidden ? 'field-hidden' : ''}`} key={label}>
        <div className='preset-label'>{label}</div>
        <div className={`preset-component ${className || ''}`}>{component}</div>
      </div>
    )
  }
  const renderFormItemList = (items = []) => {
    return items.map(x => {
      const [rendered, title, className, hidden] = x
      return renderFormItemWithLabel(
        renderFormItem(rendered),
        title,
        className,
        hidden
      )
    })
  }

  const handlePreviewSuccess = (values) => {
    setIsReview(true)
    setShowCopyButton(false)
    if (isEdit) {
      setFormVals({
        ...values,
        provider: get(editPreset, 'provider.code', ''),
        product: get(editPreset, 'product.code', ''),
        package: get(editPreset, 'package.code', ''),
        preset_type: get(editPreset, 'preset_type', '')
      })
      setSelectData({
        provider: get(editPreset, 'provider.name', ''),
        product: get(editPreset, 'product.name', ''),
        package: get(editPreset, 'package.name', '')
      })
    } else {
      if (fixedProvider) {
        setFormVals({
          ...values,
          provider: fixedProvider.code
        })
      } else {
        setFormVals(values)
      }
      setSelectData({
        provider: providerList?.find(x => fixedProvider ? x.code === fixedProvider?.code : x.code === values.provider)?.name || '',
        product: productList?.find(x => x.code === values.product)?.name || '',
        package: packageList?.find(x => x.code === values.package)?.name || ''
      })
    }
  }
  const handlePreview = () => {
    form.validateFields((err, values) => {
      if (err) {
        const errors = { ...err }
        if (values.preset_type !== 'offline') {
          delete errors.closing_slip_sla
          delete errors.quotation_slip_sla
        }
        const { stamp_duty: stampDuty, admin_fee: adminFee } = values
        let { stamp_duty: stampDutyError, admin_fee: adminFeeError } = errors
        stampDutyError = getTieringError(stampDutyError, stampDuty)
        if (!Object.keys(stampDutyError).length) {
          delete errors.stamp_duty
        }
        adminFeeError = getTieringError(adminFeeError, adminFee)
        if (!Object.keys(adminFeeError).length) {
          delete errors.admin_fee
        }
        if (!Object.keys(errors).length) {
          handlePreviewSuccess(values)
        }
      } else {
        handlePreviewSuccess(values)
      }
    })
  }

  const handleCancel = () => {
    resetFields()
  }

  const handleSubmit = () => {
    onSubmit(formToFormData(
      formVals,
      fixedProvider?.code,
      isEdit
    ))
  }
  return (
    <PresetFormStyle>
      <Form hidden={isReview}>
        {
          isEdit && renderFormItemWithLabel(
            <div className='preset-text preset-margin-bottom'>{editPreset?.code}</div>,
            'Preset Id'
          )
        }
        {
          renderFormItemWithLabel(
            renderFormItem(
              {
                placeholder: '',
                maxLength: 100,
                name: 'name',
                title: 'Preset Name',
                required: true,
                type: 'text',
                pattern: /^[\w][\w\s]*$/,
                error: 'Please Enter Preset Name with Alphanumeric Characters'
              }
            ),
            'Preset Name',
            'preset-max-width'
          )
        }
        {
          renderFormItemWithLabel(
            isEdit
              ? <div className='preset-text preset-margin-bottom'>{`${get(editPreset, 'preset_type')} Policy`}</div>
              : renderFormItem(
                {
                  type: 'radio-group',
                  name: 'preset_type',
                  required: true,
                  data: [
                    {
                      value: 'offline',
                      label: 'Offline Policy'
                    },
                    {
                      value: 'online',
                      label: 'Online Policy'
                    }
                  ],
                  title: 'Type'
                }
              ),
            'Type'
          )
        }
        {
          renderFormItemWithLabel(
            isEdit
              ? <div className='preset-text preset-margin-bottom'>{get(editPreset, 'provider.name')}</div>
              : fixedProvider
                ? (
                  <div className='preset-text preset-margin-bottom'>
                    {fixedProvider?.name}
                  </div>
                  )
                : renderFormItem(
                  {
                    placeholder: 'Select provider name',
                    name: 'provider',
                    type: 'select',
                    required: true,
                    title: 'Provider Name',
                    data: providerList,
                    dropdownKey: 'code',
                    dropdownValue: 'name',
                    showSearch: true
                  }
                ),
            'Provider Name',
            'preset-max-width'
          )
        }
        {
          renderFormItemWithLabel(
            isEdit
              ? <div className='preset-text preset-margin-bottom'>{get(editPreset, 'product.name')}</div>
              : renderFormItem({
                placeholder: 'Select product type',
                name: 'product',
                type: 'select',
                required: true,
                title: 'Product Type',
                data: productList,
                dropdownKey: 'code',
                dropdownValue: 'name',
                showSearch: true
              }),
            'Product Type',
            'preset-max-width'
          )
        }
        {
          renderFormItemWithLabel(
            isEdit
              ? <div className='preset-text preset-margin-bottom'>{get(editPreset, 'package.name')}</div>
              : renderFormItem({
                placeholder: 'Select package name',
                name: 'package',
                type: 'select',
                required: !!packageList.length,
                title: 'Package Name',
                data: packageList,
                dropdownKey: 'code',
                dropdownValue: 'name',
                showSearch: true
              }),
            'Package Name',
            'preset-max-width'
          )
        }
        {
          renderFormItemList([
            ...BF_FIELDS,
            ...DiscountFields(form.getFieldValue('agent_bf_commission_percent', 100.00)),
            ...EF_FIELDS
          ])
        }
        {
          renderFormItemWithLabel(
            <Tiering form={form} type='admin_fee' tieringData={tieringData} />,
            'Admin Fee'
          )
        }
        {
          renderFormItemWithLabel(
            renderFormItem(
              HARD_COPY_STATUS[0]
            ),
            HARD_COPY_STATUS[1]
          )
        }
        {
          renderFormItemWithLabel(
            <Tiering form={form} type='stamp_duty' tieringData={tieringData} />,
            'Stamp Duty'
          )
        }
        {
          slaElements(
            renderFormItemList,
            isEdit
              ? get(editPreset, 'preset_type') !== 'offline'
              : form.getFieldValue('preset_type') !== 'offline'
          )
        }
        {
          formDateElements(renderFormItemWithLabel, renderFormItem, disabledDate)
        }
      </Form>
      {
        isReview && <ViewPreset presetData={formVals} selectData={selectData} />
      }
      <Row type='flex' justify='end'>
        {
          isReview
            ? (
              <>
                <Button onClick={() => {
                  setIsReview(false)
                  setShowCopyButton(true)
                }}
                >
                  Back To Edit
                </Button>
                <Button onClick={handleSubmit}>Submit</Button>
              </>)
            : (
              <>
                <Button onClick={handleCancel}>Cancel</Button>
                <Button onClick={handlePreview}>Preview</Button>
              </>)
        }
      </Row>
    </PresetFormStyle>
  )
}

export default PresetForm
