import { useResetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Result, Row } from 'antd'
import { useEffect, useMemo, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'
import PresetForm from '../PresetForm'
import { PresetContextProvider } from '../../store/context'
import {
  useCreatePreset, useEditPresetDetails,
  useIndependentPackageList, usePresetDetails,
  usePresetList, useProductList, useShortProviderList, useUpdatePreset
} from '../../store/state/hooks/usePresetStore'
import CopyPreset from '../CopyPreset'
import { useHistory } from 'react-router'
import { showNotification } from '../../../../../components/ShowNotification'
import get from 'lodash/get'
import PropTypes from 'prop-types'
import { viewPresetRoute } from '../../config/urls'
const PresetFormContainer = (props) => {
  const { isEdit, editPresetId = '', form } = props
  const retryRef = useRef({
    product: 0,
    provider: 0,
    package: 0,
    preset: 0,
    editPreset: 0
  })
  const { resetError } = useResetError()
  const [fatalError, setFatalError] = useState(false)
  const history = useHistory()
  const { getFieldValue, resetFields } = form
  const [showCopyButton, setShowCopyButton] = useState(true)
  const productType = getFieldValue('product')
  const [providerCode, setProviderCode] = useState('')
  const [presetId, setPresetId] = useState('')
  const [presetEditId, setPresetEditId] = useState('')
  const [copyVisible, setCopyVisible] = useState(false)
  const formRef = useRef(form)
  const previewRef = useRef(() => {})
  const [{ getShortProviderListData }, getShortProviderListRequest] = useShortProviderList()
  const [{ getProductListData }, getProductListRequest] = useProductList()
  const [{ getPresetListData }, getPresetListRequest] = usePresetList()
  const [{ getPresetDetailsData }, getPresetDetailsRequest] = usePresetDetails()
  const [{ getEditPresetDetailsData }, getEditPresetDetailsRequest] = useEditPresetDetails()
  const [{ getIndependentPackageListData }, getIndependentPackageListRequest] = useIndependentPackageList()
  const [{ createPresetData }, createPresetRequest] = useCreatePreset()
  const [{ updatePresetData }, updatePresetRequest] = useUpdatePreset()
  const [loaderState] = useLoaderContextValue()
  const isLoader = useMemo(() => {
    const {
      GET_SHORT_PROVIDER_LIST_LOADER,
      GET_PRODUCT_LIST_LOADER, GET_PRESET_LIST_LOADER,
      GET_PRESET_DETAILS_LOADER, GET_EDIT_PRESET_DETAILS_LOADER,
      CREATE_PRESET_LOADER, GET_PACKAGE_LIST_LOADER
    } = loaderState
    return GET_SHORT_PROVIDER_LIST_LOADER ||
    GET_PRODUCT_LIST_LOADER || GET_PRESET_LIST_LOADER ||
    GET_PRESET_DETAILS_LOADER || GET_EDIT_PRESET_DETAILS_LOADER ||
    CREATE_PRESET_LOADER || GET_PACKAGE_LIST_LOADER
  }, [loaderState])
  const [{
    GET_SHORT_PROVIDER_LIST_ERROR,
    GET_PRODUCT_LIST_ERROR, GET_PRESET_LIST_ERROR,
    GET_PRESET_DETAILS_ERROR, GET_EDIT_PRESET_DETAILS_ERROR,
    GET_INDEPENDENT_PACKAGE_LIST_ERROR,
    CREATE_PRESET_ERROR, UPDATE_PRESET_ERROR,
    createPresetStatus, updatePresetStatus, getProductListStatus, getShortProviderListStatus,
    getPresetListStatus, getPresetDetailsStatus, getEditPresetDetailsStatus,
    getIndependentPackageListStatus, createPresetErrorData, updatePresetErrorData, getProductListErrorData,
    getShortProviderListErrorData, getPresetListErrorData,
    getPresetDetailsErrorData, getEditPresetDetailsErrorData, getIndependentPackageListErrorData
  }
  ] = useErrorContextValue()
  const fixedProvider = useMemo(() => {
    if (providerCode && getShortProviderListData) {
      return getShortProviderListData.find(x => x.code === providerCode)
    }
  }, [getShortProviderListData, providerCode])
  const queryParams = useMemo(() => {
    if (fixedProvider) {
      return { providerCode: fixedProvider.code }
    }
    return {}
  }, [fixedProvider])
  useEffect(() => {
    formRef.current = form
  }, [form])

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const preset = params.get('presetId')
    const provider = params.get('providerCode')
    if (preset && !isEdit) {
      setPresetId(preset)
    }
    if (provider && !isEdit) {
      setProviderCode(provider)
    }
  }, [isEdit])

  useEffect(() => {
    if (isEdit && editPresetId) {
      setPresetEditId(editPresetId)
    }
  }, [isEdit, editPresetId])

  useEffect(() => {
    getShortProviderListRequest()
    getProductListRequest()
    getPresetListRequest()
  }, [getShortProviderListRequest, getProductListRequest, getPresetListRequest])

  useEffect(() => {
    if (presetId) {
      getPresetDetailsRequest({ uuid: presetId })
      setPresetId('')
    }
  }, [presetId, getPresetDetailsRequest])

  useEffect(() => {
    if (isEdit && presetEditId) getEditPresetDetailsRequest({ uuid: presetEditId })
  }, [presetEditId, isEdit, getEditPresetDetailsRequest])

  useEffect(() => {
    if (productType) {
      resetFields(['package'])
      getIndependentPackageListRequest({
        productCode: productType
      })
    }
  }, [productType, getIndependentPackageListRequest, resetFields])

  useEffect(() => {
    if (createPresetStatus === 'success' ||
        updatePresetStatus === 'success') {
      if (isEdit) {
        showNotification('success', 'Preset Updated Successfully')
      } else {
        showNotification('success', 'A new Preset is successfully added')
      }
      resetError([
        'createPresetStatus',
        'updatePresetStatus'
      ])
      if (isEdit) {
        history.replace(viewPresetRoute(updatePresetData?.new_preset_uuid, queryParams))
      } else {
        history.replace(viewPresetRoute(createPresetData.new_preset_uuid, queryParams))
      }
    } else if (CREATE_PRESET_ERROR && createPresetStatus) {
      showNotification('error', createPresetErrorData.message)
      previewRef.current()
      resetError([
        'createPresetStatus'
      ])
    } else if (UPDATE_PRESET_ERROR && updatePresetStatus) {
      showNotification('error', updatePresetErrorData.message)
      previewRef.current()
      resetError([
        'updatePresetStatus'
      ])
    }
  }, [createPresetStatus, CREATE_PRESET_ERROR,
    updatePresetStatus, UPDATE_PRESET_ERROR, createPresetData,
    updatePresetData, createPresetErrorData, updatePresetErrorData,
    isEdit, history, resetError, queryParams])

  useEffect(() => {
    if (getProductListStatus === 'success') {
      retryRef.current.product = 0
      resetError([
        'getProductListStatus'
      ])
    } else if (GET_PRODUCT_LIST_ERROR && getProductListStatus) {
      retryRef.current.product = retryRef.current.product + 1
      if (retryRef.current.product <= 5) {
        showNotification('error', 'Failed to fetch product list, trying again...')
        resetError([
          'getProductListStatus'
        ])
        if (retryRef.current.product <= 5) {
          getProductListRequest()
        } else {
          setFatalError(true)
        }
      }
    }
  }, [GET_PRODUCT_LIST_ERROR, getProductListStatus,
    getProductListErrorData, getProductListRequest, resetError])

  useEffect(() => {
    if (getShortProviderListStatus === 'success') {
      retryRef.current.provider = 0
      resetError([
        'getShortProviderListStatus'
      ])
    } else if (GET_SHORT_PROVIDER_LIST_ERROR && getShortProviderListStatus) {
      retryRef.current.provider = retryRef.current.provider + 1
      if (retryRef.current.provider <= 5) {
        showNotification('error', 'Failed to fetch provider list, trying again...')
        resetError([
          'getShortProviderListStatus'
        ])
        getShortProviderListRequest()
      } else {
        setFatalError(true)
      }
    }
  }, [GET_SHORT_PROVIDER_LIST_ERROR, getShortProviderListStatus,
    getShortProviderListErrorData, getShortProviderListRequest, resetError])

  useEffect(() => {
    if (getPresetListStatus === 'success') {
      retryRef.current.preset = 0
      resetError([
        'getPresetListStatus'
      ])
    } else if (GET_PRESET_LIST_ERROR && getPresetListStatus) {
      retryRef.current.preset = retryRef.current.preset + 1
      if (retryRef.current.preset <= 5) {
        showNotification('error', 'Failed to fetch preset list, trying again...')
        resetError([
          'getPresetListStatus'
        ])
        getPresetListRequest()
      } else {
        setFatalError(true)
      }
    }
  }, [GET_PRESET_LIST_ERROR, getPresetListStatus,
    getPresetListErrorData, getPresetListRequest, resetError])

  useEffect(() => {
    if (getIndependentPackageListStatus === 'success') {
      resetError([
        'getIndependentPackageListStatus'
      ])
    } else if (GET_INDEPENDENT_PACKAGE_LIST_ERROR && getIndependentPackageListStatus) {
      showNotification('error', get(getIndependentPackageListErrorData, 'message', 'failed to fetch package list'))
      resetError([
        'getIndependentPackageListStatus'
      ])
    }
  }, [GET_INDEPENDENT_PACKAGE_LIST_ERROR, getIndependentPackageListStatus,
    getIndependentPackageListErrorData, resetError])

  useEffect(() => {
    if (getEditPresetDetailsStatus === 'success') {
      retryRef.current.editPreset = 0
      resetError([
        'getEditPresetDetailsStatus'
      ])
    } else if (GET_EDIT_PRESET_DETAILS_ERROR && getEditPresetDetailsStatus) {
      retryRef.current.preset = retryRef.current.preset + 1
      if (retryRef.current.preset <= 5) {
        showNotification('error', `${get(getEditPresetDetailsErrorData, 'message', 'failed to fetch preset details')}, trying again...`)
        resetError([
          'getEditPresetDetailsStatus'
        ])
        getEditPresetDetailsRequest()
      } else {
        setFatalError(true)
      }
    }
  }, [GET_EDIT_PRESET_DETAILS_ERROR, getEditPresetDetailsStatus,
    getEditPresetDetailsErrorData, getEditPresetDetailsRequest, resetError])

  useEffect(() => {
    if (getPresetDetailsStatus === 'success') {
      resetError([
        'getPresetDetailsStatus'
      ])
    } else if (GET_PRESET_DETAILS_ERROR && getPresetDetailsStatus) {
      showNotification('error', get(getPresetDetailsErrorData, 'message', 'failed to fetch preset details'))
      resetError([
        'getPresetDetailsStatus'
      ])
    }
  }, [GET_PRESET_DETAILS_ERROR, getPresetDetailsStatus,
    getPresetDetailsErrorData, resetError])

  const onSubmit = (data) => {
    if (isEdit) {
      updatePresetRequest({
        uuid: editPresetId,
        body: data
      })
    } else {
      createPresetRequest({
        body: data
      })
    }
  }
  const onCopyPreset = ({ preset }) => {
    if (preset) {
      setPresetId(preset)
      setCopyVisible(false)
    }
  }

  if (fatalError) {
    return (
      <Result
        status='500'
        title='Oops!'
        subTitle='Sorry, something went wrong. Try reloading the page, if problem persists come back again later.'
        extra={<Button type='primary' onClick={() => window.location.reload()}>Reload</Button>}
      />
    )
  }
  return (
    <CircularLoader
      isSpining={isLoader}
    >
      <Row type='flex' justify='space-between'>
        <Button onClick={() => history.goBack()}>Back</Button>
        {
          showCopyButton &&
            <Button
              onClick={() => setCopyVisible(true)}
              type='primary'
            >
              Copy Existing Preset
            </Button>
        }
      </Row>
      <PresetForm
        {...props}
        packageList={getIndependentPackageListData}
        providerList={getShortProviderListData}
        productList={getProductListData}
        fixedProvider={fixedProvider}
        onSubmit={onSubmit}
        presetData={getPresetDetailsData}
        editPresetData={getEditPresetDetailsData}
        setShowCopyButton={setShowCopyButton}
        previewRef={previewRef}
      />
      <CopyPreset
        visible={copyVisible}
        onCancel={() => setCopyVisible(false)}
        onSubmit={onCopyPreset}
        presetList={getPresetListData || []}
      />
    </CircularLoader>
  )
}

PresetFormContainer.propTypes = {
  isEdit: PropTypes.bool,
  editPresetId: PropTypes.string
}

const WrappedPresetFormContainer = Form.create()(PresetFormContainer)
const WithContextPresetFormContainer = (props) => (
  <PresetContextProvider>
    <WrappedPresetFormContainer {...props} />
  </PresetContextProvider>
)

export default WithContextPresetFormContainer
